create or replace function public.business_location_scoped_analytics(p_business_id uuid,p_location_id uuid,p_dataset text,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare r jsonb; begin if not exists(select 1 from locations where id=p_location_id and business_id=p_business_id) then raise exception 'Location does not belong to business'; end if; if p_dataset='overview' then select jsonb_build_object('locations',1,'active_locations',count(*) filter(where is_active),'visits',(select count(*) from location_visits where location_id=p_location_id and occurred_at between p_start and p_end),'unique_users',(select count(distinct user_id) from location_visits where location_id=p_location_id and occurred_at between p_start and p_end),'check_ins',(select count(*) from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end),'checkin_users',(select count(distinct user_id) from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end),'reviews',(select count(*) from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'),'average_rating',coalesce((select avg(stars) from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'),0),'programs',0,'events',(select count(*) from business_events where location_id=p_location_id and(event_date is null or event_date between p_start::date and p_end::date)),'promotions',(select count(*) from promotions where location_id=p_location_id)) into r from locations where id=p_location_id; elsif p_dataset='locations' then select jsonb_build_object('locations',1,'active_locations',count(*) filter(where is_active),'check_ins',(select count(*) from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end),'unique_visitors',(select count(distinct user_id) from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end),'reviews',(select count(*) from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'),'average_rating',coalesce((select avg(stars) from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'),0)) into r from locations where id=p_location_id; elsif p_dataset='qr' then select jsonb_build_object('qr_scans',count(*) filter(where verification_method='qr'),'check_ins',count(*),'unique_users',count(distinct user_id),'locations',1,'locations_with_scans',case when count(*) filter(where verification_method='qr')>0 then 1 else 0 end,'last_scan_at',max(checked_in_at) filter(where verification_method='qr')) into r from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end; elsif p_dataset='reviews' then select jsonb_build_object('reviews',count(*),'average_rating',coalesce(avg(stars),0),'cleanliness_pct',coalesce(avg(cleanliness_pct),0),'published_reviews',count(*) filter(where status='published'),'business_replies',count(*) filter(where business_reply is not null)) into r from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'; elsif p_dataset='photos' then select jsonb_build_object('photos',count(*),'vr_photos',count(*) filter(where lower(coalesce(media_type,'')) in('vr','360','360_vr')),'storage_bytes',coalesce(sum(size_bytes),0),'average_size_bytes',coalesce(avg(size_bytes),0),'uploads',count(*)) into r from location_photos where location_id=p_location_id and created_at between p_start and p_end; elsif p_dataset='promotions' then select jsonb_build_object('promotions',count(*),'active_promotions',count(*) filter(where active),'promotion_views',(select count(*) from analytics_events where location_id=p_location_id and event_type='promotion_view' and created_at between p_start and p_end),'redemptions',(select count(*) from analytics_events where location_id=p_location_id and event_type='promotion_redeemed' and created_at between p_start and p_end),'unique_redeemers',(select count(distinct user_id) from analytics_events where location_id=p_location_id and event_type='promotion_redeemed' and created_at between p_start and p_end),'conversion_rate_pct',case when (select count(*) from analytics_events where location_id=p_location_id and event_type='promotion_view' and created_at between p_start and p_end)=0 then 0 else round(100.0*(select count(*) from analytics_events where location_id=p_location_id and event_type='promotion_redeemed' and created_at between p_start and p_end)/(select count(*) from analytics_events where location_id=p_location_id and event_type='promotion_view' and created_at between p_start and p_end),2) end) into r from promotions where location_id=p_location_id; elsif p_dataset='rewards' then select jsonb_build_object('check_ins',count(*),'points_awarded',coalesce(sum(points_awarded),0),'reward_events',count(*) filter(where coalesce(points_awarded,0)>0),'reward_points',coalesce(sum(points_awarded),0)) into r from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end; elsif p_dataset='events' then select jsonb_build_object('events',count(*),'rsvps',coalesce((select count(distinct er.user_id) from event_rsvps er where er.event_id in(select id from business_events where location_id=p_location_id and(event_date is null or event_date between p_start::date and p_end::date))),0),'event_views',coalesce((select count(*) from analytics_events where location_id=p_location_id and event_type='location_view' and created_at between p_start and p_end),0),'event_rsvps_tracked',coalesce((select count(*) from analytics_events where location_id=p_location_id and event_type='event_rsvp' and created_at between p_start and p_end),0)) into r from business_events where location_id=p_location_id and(event_date is null or event_date between p_start::date and p_end::date); elsif p_dataset='growth' then select jsonb_build_object('check_ins',count(*),'unique_users',count(distinct user_id),'reviews',(select count(*) from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'),'new_users',0,'locations',1,'active_locations',case when (select is_active from locations where id=p_location_id) then 1 else 0 end) into r from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end; elsif p_dataset='visitors' then with v as(select user_id,occurred_at from location_visits where location_id=p_location_id and occurred_at between p_start and p_end union all select user_id,checked_in_at from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end),c as(select user_id,count(*) n from v group by user_id) select jsonb_build_object('visits',(select count(*) from v),'unique_visitors',(select count(*) from c),'repeat_visitors',(select count(*) from c where n>1),'new_visitors',(select count(*) from c where user_id not in(select user_id from check_ins where location_id=p_location_id and checked_in_at<p_start)),'returning_visitors',(select count(*) from c where user_id in(select user_id from check_ins where location_id=p_location_id and checked_in_at<p_start)),'retention_rate_pct',case when (select count(*) from c)=0 then 0 else round(100.0*(select count(*) from c where n>1)/(select count(*) from c),2) end) into r; else r:=null; end if; return r; end $$; grant execute on function public.business_location_scoped_analytics(uuid,uuid,text,timestamptz,timestamptz) to authenticated;
